<?php
namespace App\Http\Controllers; use App\Models\{InventoryItem,InventoryMovement,Supplier,Notification,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class InventoryController extends Controller {
 public function index(Request $r){$q=InventoryItem::with('supplier');if($r->q)$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('sku','like','%'.$r->q.'%'));if($r->low)$q->whereColumn('quantity','<=','reorder_level');return view('inventory.index',['items'=>$q->orderBy('name')->paginate(15)->withQueryString(),'suppliers'=>Supplier::orderBy('name')->get()]);}
 public function store(Request $r){InventoryItem::create($this->data($r));return back()->with('success','Inventory item created.');}
 public function update(Request $r,InventoryItem $inventory){$inventory->update($this->data($r,$inventory));return back()->with('success','Item updated.');}
 public function destroy(InventoryItem $inventory){$inventory->delete();return back()->with('success','Item deleted.');}
 public function movement(Request $r,InventoryItem $inventory){$d=$r->validate(['movement_type'=>'required|in:in,out,adjustment','quantity'=>'required|integer','note'=>'nullable|string|max:255']);if($d['movement_type']!=='adjustment'&&$d['quantity']<1)return back()->withErrors(['quantity'=>'Quantity must be at least 1.']);DB::transaction(function()use($inventory,$d,$r){$before=$inventory->quantity;if($d['movement_type']==='in')$inventory->quantity += $d['quantity'];elseif($d['movement_type']==='out'){$inventory->quantity -= $d['quantity'];if($inventory->quantity<0)throw \Illuminate\Validation\ValidationException::withMessages(['quantity'=>'Not enough stock available.']);}else{$inventory->quantity=$d['quantity'];}$inventory->save();InventoryMovement::create(['item_id'=>$inventory->id,'movement_type'=>$d['movement_type'],'quantity'=>$d['quantity'],'note'=>$d['note']??null,'created_by'=>$r->user()->id]);if($inventory->quantity<=$inventory->reorder_level && $before>$inventory->reorder_level){foreach(User::where('role','admin')->where('active',true)->get() as $u)Notification::create(['user_id'=>$u->id,'title'=>'Low stock alert','message'=>$inventory->name.' is at '.$inventory->quantity.' units.','type'=>'warning']);}});return back()->with('success','Stock updated.');}
 private function data(Request $r,?InventoryItem $item=null){return $r->validate(['name'=>'required|string|max:120','sku'=>'nullable|string|max:60|unique:inventory_items,sku,'.($item?->id??'NULL'),'category'=>'nullable|string|max:80','quantity'=>'required|integer|min:0','reorder_level'=>'required|integer|min:0','cost_price'=>'required|numeric|min:0','sale_price'=>'required|numeric|min:0','supplier_id'=>'nullable|exists:suppliers,id']);}
}
